domize: false // uses random initial node positions on true\n};\nexports.random_options = {\n    name: 'random',\n    fit: true, // whether to fit to viewport\n    padding: 20, // fit padding\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    animate: true, // whether to transition the node positions\n    animationDuration: 1500, // duration of animation in ms if enabled\n    // animationEasing: 'linear', // easing of animation if enabled\n    // animateFilter: (node, i) => { return true; }, // a function that determines whether the node should be animated.  All nodes animated by default on animate enabled.  Non-animated nodes are positioned immediately when the layout starts\n    ready: undefined, // callback on layoutready\n    stop: undefined // callback on layoutstop\n    // transform: (node, position)=> { return position; } // transform a given node position. Useful for changing flow direction in discrete layouts\n};\nexports.grid_options = {\n    name: 'grid',\n    fit: true, // whether to fit the viewport to the graph\n    padding: 20, // padding used on fit\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    avoidOverlap: true, // prevents node overlap, may overflow boundingBox if not enough space\n    avoidOverlapPadding: 100, // extra spacing around nodes when avoidOverlap: true\n    nodeDimensionsIncludeLabels: true, // Excludes the label when calculating node bounding boxes for the layout algorithm\n    spacingFactor: undefined, // Applies a multiplicative factor (>0) to expand or compress the overall area that the nodes take up\n    condense: false, // uses all available space on false, uses minimal space on true\n    rows: undefined, // force num of rows in the grid\n    cols: undefined, // force num of columns in the grid\n    position: (_node) => undefined, // returns { row, col } for element\n    // sort: (a: cytoscape.SortableNode, b: cytoscape.SortableNode) {\n    //     return (a as cytoscape.SingularElement).degree(false) - (b as cytoscape.SingularElement).degree(false);\n    // }, // a sorting function to order the nodes; e.g. function(a, b){ return a.data('weight') - b.data('weight') }\n    animate: true, // whether to transition the node positions\n    animationDuration: 1500, // duration of animation in ms if enabled\n    ready: undefined, // callback on layoutready\n    stop: undefined // callback on layoutstop\n};\nexports.circle_options = {\n    name: 'circle',\n    fit: true, // whether to fit the viewport to the graph\n    padding: 30, // the padding on fit\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    avoidOverlap: true, // prevents node overlap, may overflow boundingBox and radius if not enough space\n    nodeDimensionsIncludeLabels: true, // Excludes the label when calculating node bounding boxes for the layout algorithm\n    spacingFactor: undefined, // Applies a multiplicative factor (>0) to expand or compress the overall area that the nodes take up\n    radius: undefined, // the radius of the circle\n    startAngle: 3 / 2 * Math.PI, // where nodes start in radians\n    sweep: undefined, // how many radians should be between the first and last node (defaults to full circle)\n    clockwise: true, // whether the layout should go clockwise (true) or counterclockwise/anticlockwise (false)\n    // sort:  (a, _b) => {\n    //     return a.data('type') <= a.data('type')\n    // }, // a sorting function to order the nodes; e.g. function(a, b){ return a.data('weight') - b.data('weight') }\n    animate: true, // whether to transition the node positions\n    animationDuration: 1500, // duration of animation in ms if enabled\n    ready: undefined, // callback on layoutready\n    stop: undefined // callback on layoutstop\n};\nexports.concentric_options = {\n    name: 'concentric',\n    fit: true, // whether to fit the viewport to the graph\n    padding: 30, // the padding on fit\n    startAngle: 3 / 2 * Math.PI, // where nodes start in radians\n    sweep: undefined, // how many radians should be between the first and last node (defaults to full circle)\n    clockwise: true, // whether the layout should go clockwise (true) or counterclockwise/anticlockwise (false)\n    equidistant: false, // whether levels have an equal radial distance betwen them, may cause bounding box overflow\n    minNodeSpacing: 100, // min spacing between outside of nodes (used for radius adjustment)\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    avoidOverlap: true, // prevents node overlap, may overflow boundingBox if not enough space\n    nodeDimensionsIncludeLabels: true, // Excludes the label when calculating node bounding boxes for the layout algorithm\n    height: undefined, // height of layout area (overrides container height)\n    width: undefined, // width of layout area (overrides container width)\n    spacingFactor: undefined, // Applies a multiplicative factor (>0) to expand or compress the overall area that the nodes take up\n    concentric: (node) => {\n        return node.degree();\n    },\n    levelWidth: (nodes) => {\n        // return nodes.maxDegree() / 6;\n        return nodes.maxDegree() / 8;\n    },\n    animate: true, // whether to transition the node positions\n    animationDuration: 2000, // duration of animation in ms if enabled\n    animationEasing: undefined, // easing of animation if enabled\n    ready: undefined, // callback on layoutready\n    stop: undefined // callback on layoutstop\n};\nexports.breadthfirst_options = {\n    name: 'breadthfirst',\n    fit: true, // whether to fit the viewport to the graph\n    directed: false, // whether the tree is directed downwards (or edges can point in any direction if false)\n    padding: 50, // padding on fit\n    circle: true, // put depths in concentric circles if true, put depths top down if false\n    spacingFactor: 2, // positive spacing factor, larger => more space between nodes (N.B. n/a if causes overlap)\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    avoidOverlap: true, // prevents node overlap, may overflow boundingBox if not enough space\n    nodeDimensionsIncludeLabels: true, // Excludes the label when calculating node bounding boxes for the layout algorithm\n    roots: undefined, // the roots of the trees\n    maximalAdjustments: 5, // how many times to try to position the nodes in a maximal way (i.e. no backtracking)\n    animate: true, // whether to transition the node positions\n    animationDuration: 3000, // duration of animation in ms if enabled\n    // animationEasing: 'ease-in-out', // easing of animation if enabled,\n    // animateFilter: function (node, i) { return true; }, // a function that determines whether the node should be animated.  All nodes animated by default on animate enabled.  Non-animated nodes are positioned immediately when the layout starts\n    ready: undefined, // callback on layoutready\n    stop: undefined // callback on layoutstop\n};\nexports.dagre_options = {\n    name: 'dagre',\n    // dagre algo options, uses default value on undefined\n    nodeSep: undefined, // the separation between adjacent nodes in the same rank\n    edgeSep: undefined, // the separation between adjacent edges in the same rank\n    rankSep: undefined, // the separation between adjacent nodes in the same rank\n    rankDir: undefined, // 'TB' for top to bottom flow, 'LR' for left to right,\n    ranker: 'network-simplex', // Type of algorithm to assign a rank to each node in the input graph. Possible values: 'network-simplex', 'tight-tree' or 'longest-path'\n    minLen: (_edge) => 1, // number of ranks to keep between the source and target of the edge\n    edgeWeight: (_edge) => 1, // higher weight edges are generally made shorter and straighter than lower weight edges\n    // general layout options\n    fit: true, // whether to fit to viewport\n    padding: 30, // fit padding\n    spacingFactor: undefined, // Applies a multiplicative factor (>0) to expand or compress the overall area that the nodes take up\n    nodeDimensionsIncludeLabels: true, // whether labels should be included in determining the space used by a node (default true)\n    animate: true, // whether to transition the node positions\n    animateFilter: (_node, _i) => true, // whether to animate specific nodes when animation is on; non-animated nodes immediately go to their final positions\n    animationDuration: 1500, // duration of animation in ms if enabled\n    animationEasing: 'ease-in-out', // easing of animation if enabled\n    boundingBox: undefined, // constrain layout bounds; { x1, y1, x2, y2 } or { x1, y1, w, h }\n    transform: (_node, pos) => pos, // a function that applies a transform to the final node position\n    ready: () => { }, // on layoutready\n    stop: () => { } // on layoutstop\n};\nexports.euler_options = {\n    name: 'euler',\n    // The ideal length of a spring\n    // - This acts as a hint for the edge length\n    // - The edge length can be longer or shorter if the forces are set to extreme values\n    springLength: (_edge) => 200,\n    // Hooke's law coefficient\n    // - The value ranges on [0, 1]\n    // - Lower values give looser springs\n    // - Higher values give tighter springs\n    springCoeff: (_edge) => 0.0008,\n    // The mass of the node in the physics simulation\n    // - The mass affects the gravity node repulsion/attraction\n    mass: (_node) => 4,\n    // Coulomb's law coefficient\n    // - Makes the nodes repel each other for negative values\n    // - Makes the nodes attract each other for positive values\n    gravity: -1.2,\n    // A force that pulls nodes towards the origin (0, 0)\n    // Higher values keep the components less spread out\n    pull: 0.001,\n    // Theta coefficient from Barnes-Hut simulation\n    // - Value ranges on [0, 1]\n    // - Performance is better with smaller values\n    // - Very small values may not create enough force to give a good result\n    theta: 0.666,\n    // Friction / drag coefficient to make the system stabilise over time\n    dragCoeff: 0.02,\n    // When the total of the squared position deltas is less than this value, the simulation ends\n    movementThreshold: 1,\n    // The amount of time passed per tick\n    // - Larger values result in faster runtimes but might spread things out too far\n    // - Smaller values produce more accurate results\n    timeStep: 20,\n    // The number of ticks per frame for animate:true\n    // - A larger value reduces rendering cost but can be jerky\n    // - A smaller value increases rendering cost but is smoother\n    refresh: 10,\n    // Whether to animate the layout\n    // - true : Animate while the layout is running\n    // - false : Just show the end result\n    // - 'end' : Animate directly to the end result\n    animate: true,\n    // Animation duration used for animate:'end'\n    animationDuration: 1500,\n    // Easing for animate:'end'\n    animationEasing: undefined,\n    // Maximum iterations and time (in ms) before the layout will bail out\n    // - A large value may allow for a better result\n    // - A small value may make the layout end prematurely\n    // - The layout may stop before this if it has settled\n    maxIterations: 1000,\n    maxSimulationTime: 4000,\n    // Prevent the user grabbing nodes during the layout (usually with animate:true)\n    ungrabifyWhileSimulating: true,\n    // Whether to fit the viewport to the repositioned graph\n    // true : Fits at end of layout for animate:false or animate:'end'; fits on each frame for animate:true\n    fit: true,\n    // Padding in rendered co-ordinates around the layout\n    padding: 20,\n    // Constrain layout bounds with one of\n    // - { x1, y1, x2, y2 }\n    // - { x1, y1, w, h }\n    // - undefined / null : Unconstrained\n    boundingBox: undefined,\n    // Layout event callbacks; equivalent to `layout.one('layoutready', callback)` for example\n    ready: () => { }, // on layoutready\n    stop: () => { }, // on layoutstop\n    // Whether to randomize the initial positions of the nodes\n    // true : Use random positions within the bounding box\n    // false : Use the current node positions as the initial positions\n    randomize: false\n};\nexports.layouts = {\n    spread: exports.spread_options,\n    cola: exports.cola_layout_options,\n    cose: exports.cose_options,\n    cose_bilkent: exports.cose_bilkent_options,\n    klay: exports.klay_options,\n    dagre: exports.dagre_options,\n    euler: exports.euler_options,\n    // ngraph: ngraph_options,\n    random: exports.random_options,\n    grid: exports.grid_options,\n    circle: exports.circle_options,\n    concentric: exports.concentric_options,\n    breadthfirst: exports.breadthfirst_options\n};\n\n\n//# sourceURL=webpack://stig/./src/graph/graphOptions.ts?");

